  3	namespace Modules\AI\Infrastructure\Battle;
  4	
  5	use Modules\AI\Domain\Raid\RaidEstimate;
  6	use OGame\Factories\PlanetServiceFactory;
  7	use OGame\Factories\PlayerServiceFactory;
  8	use OGame\GameMissions\BattleEngine\BattleEngine;
  9	use OGame\GameMissions\BattleEngine\Models\AttackerFleet;
 10	use OGame\GameMissions\BattleEngine\Models\DefenderFleet;
 11	use OGame\GameMissions\BattleEngine\PhpBattleEngine;
 12	use OGame\GameMissions\BattleEngine\RustBattleEngine;
 13	use OGame\GameObjects\Models\Units\UnitCollection;
 14	use OGame\Models\Resources;
 15	use OGame\Services\SettingsService;
 16	
 17	/**
 18	 * The native raid estimator: samples the host's own battle engine as a read-only
 19	 * question.
 20	 *
 21	 * It is not a second battle implementation. Every run asks
 22	 * `simulateBattle($seed, true)` — the pure, seeded shape R1 added — on the engine
 23	 * the host itself fights with (`SettingsService::battleEngine()`), so the engine
 24	 * stays the authority on the rules and a "what if" never touches the world. Both
 25	 * engines are seeded: the Rust FFI carries the seed in its input and derives one
 26	 * stream per side per round, so a screen replays identically whichever engine the
 27	 * universe runs. Rust is roughly 7x faster per simulation, which is why the
 28	 * module no longer pins the PHP engine.
 29	 *
 30	 * The fleet is the account's own ships on the origin planet, and the defender is
 31	 * the host's stationary picture of the target planet, so no unit, price or
 32	 * defence figure is named here.
 33	 */
 34	class NativeRaidEstimator
 35	{
 36	    private const SCREEN_SAMPLES = 50;
 37	
 38	    private const CRYSTAL_WEIGHT = 1.5;
 39	
 40	    private const DEUTERIUM_WEIGHT = 2.0;
 41	
 42	    public function __construct(
 43	        private PlayerServiceFactory $playerServiceFactory,
 44	        private PlanetServiceFactory $planetServiceFactory,
 45	        private SettingsService $settings,
 46	    ) {
 47	    }
 48	
 49	    public function estimate(int $playerId, int $originPlanetId, int $targetPlanetId, int $seed): RaidEstimate
 50	    {
 51	        return $this->screen($playerId, $originPlanetId, $targetPlanetId, null, $seed, self::SCREEN_SAMPLES);
 52	    }
 53	
 54	    /**
 55	     * One simulation of a specific fleet against the target — the launch-subset screen (U6). The
 56	     * fleet is what the caller counter-selected; the engine and the defender stay the host's. The
 57	     * sample count is the caller's ladder rung: one draw for a candidate screen, the wide pass for
 58	     * the winner's confirmation.
 59	     */
 60	    public function estimateFleet(int $playerId, int $originPlanetId, int $targetPlanetId, UnitCollection $fleet, int $seed, int $samples = 1): RaidEstimate
 61	    {
 62	        return $this->screen($playerId, $originPlanetId, $targetPlanetId, $fleet, $seed, $samples);
 63	    }
 64	
 65	    private function screen(int $playerId, int $originPlanetId, int $targetPlanetId, ?UnitCollection $fleet, int $seed, int $samples): RaidEstimate
 66	    {
 67	        $player = $this->playerServiceFactory->make($playerId, true);
 68	        $origin = $this->planetServiceFactory->makeForPlayer($player, $originPlanetId, false);
 69	        $target = $this->planetServiceFactory->make($targetPlanetId, true);
 70	
 71	        if ($target === null) {
 72	            return app()->makeWith(RaidEstimate::class, [
 73	                'samples' => 0,
 74	                'p20NetProfit' => 0.0,
 75	                'p20Loot' => 0.0,
 76	                'pWin' => 0.0,
 77	            ]);
 78	        }
 79	
 80	        $ships = $fleet ?? $origin->getShipUnits();
 81	        if ($ships->units === []) {
 82	            return app()->makeWith(RaidEstimate::class, [
 83	                'samples' => 0,
 84	                'p20NetProfit' => 0.0,
 85	                'p20Loot' => 0.0,
 86	                'pWin' => 0.0,
 87	            ]);
 88	        }
 89	
 90	        $attacker = new AttackerFleet();
 91	        $attacker->units = $ships;
 92	        $attacker->player = $player;
 93	        $attacker->fleetMissionId = 0;
 94	        $attacker->ownerId = $playerId;
 95	        $attacker->cargoResources = new Resources();
 96	        $attacker->isInitiator = true;
 97	        $attacker->fleetMission = null;
 98	
 99	        $defender = DefenderFleet::fromPlanet($target);
100	
101	        // The engine the host fights with, not one the module prefers: an
102	        // operator who pins `php` gets the same simulator their battles use.
103	        $engine = match ($this->settings->battleEngine()) {
104	            'php' => new PhpBattleEngine([$attacker], $target, [$defender], $this->settings),
105	            default => new RustBattleEngine([$attacker], $target, [$defender], $this->settings),
106	        };
107	
108	        // The screen is the one bounded pass the decision path may afford; the
109	        // confirmation is a wider sample on the winner only.
110	        $sampled = $this->sample($engine, $seed, $samples);
111	
112	        return app()->makeWith(RaidEstimate::class, [
113	            'samples' => count($sampled['netProfits']),
114	            'p20NetProfit' => $this->lowerQuantile($sampled['netProfits'], 0.2),
115	            'p20Loot' => $this->lowerQuantile($sampled['loots'], 0.2),
116	            'pWin' => $sampled['survived'] / max(1, count($sampled['netProfits'])),
117	        ]);
118	    }
119	
120	    /**
121	     * One bounded screen: the same seed + i stream yields the P20 net (survival),
122	     * the P20 loot (worth-flying) and the survived-run count (fleet survival)
123	     * from identical draws — never a second pass.
124	     *
125	     * @return array{netProfits: list<float>, loots: list<float>, survived: int}
126	     */
127	    private function sample(BattleEngine $engine, int $seed, int $samples): array
128	    {
129	        $netProfits = [];
130	        $loots = [];
131	        $survived = 0;
132	
133	        for ($i = 0; $i < $samples; $i++) {
134	            // One shared stream: seed + i, so a candidate is always compared
135	            // through the same sequence of draws.
136	            $result = $engine->simulateBattle($seed + $i, true);
137	
138	            $loots[] = $this->metalEquivalent($result->loot);
139	            $netProfits[] = $loots[$i] - $this->metalEquivalent($result->attackerResourceLoss);
140	
141	            // getAmount(), not ->units === []: the round sanitizer keeps
142	            // zero-amount entries, so a wiped fleet reads as an empty amount.
143	            $survived += $result->attackerUnitsResult->getAmount() > 0 ? 1 : 0;
144	        }
145	
146	        return ['netProfits' => $netProfits, 'loots' => $loots, 'survived' => $survived];
147	    }
148	
149	    /**
150	     * @param list<float> $values
151	     */
152	    private function lowerQuantile(array $values, float $quantile): float
153	    {
154	        sort($values);
155	        $rank = (int) ceil($quantile * count($values)) - 1;
156	
157	        return $values[max(0, min($rank, count($values) - 1))];
158	    }
159	
160	    public function metalEquivalent(Resources $resources): float
161	    {
162	        return $resources->metal->get()
163	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
164	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
165	    }
166	}

